 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                rr, cc = stack.pop()
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        cells.add((nr, nc))
                        stack.append((nr, nc))
            objects.append((color, cells))

    # Objects slide right, starting with the rightmost ones. Each stops at
    # the edge or against an object already packed farther to the right.
    objects.sort(key=lambda item: max(c for _, c in item[1]), reverse=True)
    placed = []
    result = [[0] * w for _ in range(h)]
    for color, cells in objects:
        shift = 0
        while True:
            nxt = shift + 1
            if any(c + nxt >= w for _, c in cells):
                break
            if any((r, c + nxt) in occupied for r, c in cells for occupied in placed):
                break
            shift = nxt
        moved = {(r, c + shift) for r, c in cells}
        placed.append(moved)
        for r, c in moved:
            result[r][c] = color
    return result
